export type TestMark = { state: "ok" | "bad"; rev: number; note?: string; at: string };
export type TestMarks = Record<string, TestMark>;
export const stepKey = (section: string, step: string) => `${section}.${step}`;
/** حالة الخطوة. الصح يبقى صح وما يرجع. المشكلة ترجع («changed») بس لمن تنصلح، يعني لمن يزيد رقم نسخة الخطوة */
export function stepState(step: { rev?: number }, mark?: TestMark): "ok" | "bad" | "changed" | "todo" {
  if (!mark) return "todo";
  if (mark.state === "ok") return "ok";
  return mark.rev === (step.rev ?? 1) ? "bad" : "changed";
}
